INSERT INTO muntha_bhava_phal (house,band,language,phal_text) VALUES
(1,'शुभ (उद्यम)','hi','शत्रु-नाश, मन में प्रसन्नता, मान-पुत्र-वाहन लाभ, प्रताप-वृद्धि, राजा की प्रसन्नता, देह-पुष्टि; अनेक उद्यमों से धन। (श्लोक 5)'),
(2,'शुभ (उद्यम)','hi','अपने उत्साह से धन-प्राप्ति, यश का भागी, बन्धुजनों से सम्मान, राजाश्रय से मिष्टान्न-भोग, बल-पुष्टि व सुख। (श्लोक 6)'),
(3,'शुभ (उद्यम)','hi','अपने ही पराक्रम से धन-यश-सुख, भाई-बहनों का सुख, ब्राह्मण-देव पूजा, सबका उपकार, दृढ़ शरीर, प्रसिद्धि व राजाश्रय। (श्लोक 7)'),
(4,'अशुभ','hi','शरीर-पीड़ा, दुश्मन का डर, कुटुम्बी जनों से वैर, मन में दुख, निरुद्यमता (बेकारी), जनापवाद और अनेक रोगों की वृद्धि। (श्लोक 8)'),
(5,'शुभ (उद्यम)','hi','सद्बुद्धि, सुख, पुत्र व द्रव्य का लाभ, प्रताप-वृद्धि, विविध विलास, देव-ब्राह्मण भक्ति तथा राजा की प्रसन्नता। (श्लोक 9)'),
(6,'अशुभ','hi','अंगों में दुर्बलता/दुबलापन, शत्रुओं की उत्पत्ति, रोग, चोर व राजा से भय, कार्य-धन का नाश, दुर्बुद्धि-वृद्धि, अपने कर्मों पर पश्चाताप। (श्लोक 10)'),
(7,'अशुभ','hi','स्त्री व बन्धुजनों से दुःख, व्यसन-भय, दुश्मन का डर, उत्साह-भंग, धन-धर्म हानि, शरीर-रोग, मन में मोह, विरुद्ध चेष्टाएँ। (श्लोक 11)'),
(8,'अशुभ','hi','शत्रु-चोर से भय, धन-धर्म का नाश, कष्ट/दुर्व्यसन, अधिक रोग, बल-क्षय और दूर-देश गमन। (श्लोक 12)'),
(9,'अति शुभ','hi','स्वामित्व-पद, राजा से धन-प्राप्ति, धर्म-उत्सव, पुत्र-पत्नी सुख, देव-ब्राह्मण पूजन, परम यश और भाग्योदय। (श्लोक 13)'),
(10,'अति शुभ','hi','राजा की प्रसन्नता, स्वजनों का उपकार, सत्कर्म-सिद्धि, द्विज-देव भक्ति, यश-वृद्धि, विविध धन-लाभ व पद/स्थान-प्राप्ति। (श्लोक 14)'),
(11,'अति शुभ','hi','विलास, सौभाग्य, आरोग्य, चित्त-प्रसन्नता, राजाश्रय से धन, उत्तम ज्ञान, मित्र-लाभ, पुत्र व वांछित पदार्थों की प्राप्ति। (श्लोक 15)'),
(12,'अशुभ','hi','अधिक व्यय, दुष्ट-जनों का संग, देह-रोग, पराक्रम करने पर भी कार्य-असिद्धि, धर्म-धन हानि, सज्जनों से भी वैर। (श्लोक 16)')
INSERT INTO muntha_graha_phal (rule_key,language,situation,phal_text,nature) VALUES
('Sun','hi','सूर्य-युत / सूर्य-दृष्ट / सिंह राशि में','अर्थ-राज्य लाभ, राजा की संगति, गुणों की परम उन्नति, उच्च स्थान/स्थानान्तर की प्राप्ति; कुलानुसार राज्य-सुख, स्त्री-कपड़े-भूषण भोग। (श्लोक 24)','शुभ'),
('Moon','hi','चन्द्र-युत / चन्द्र-दृष्ट / कर्क में','धर्म-यश की वृद्धि, धन, आरोग्य, संतोष व बुद्धि-वृद्धि; साथ में पाप-दृष्टि हो तो अति-दुःख। (श्लोक 25)','शुभ'),
('Mars','hi','मंगल-युत / मंगल-दृष्ट / मेष-वृश्चिक में','उष्णता-सहित पित्त-ज्वर, शस्त्र से घाव, खून-विकार; शनि-गृह (मकर-कुम्भ) में या शनि-दृष्ट हो तो यह फल घटता है — तब शनि-मंगल का फल समान। (श्लोक 26)','अशुभ'),
('Mercury_Venus','hi','बुध/शुक्र-युत या दृष्ट / मिथुन-कन्या-वृषभ-तुला में','स्त्री-सुख, बुद्धि का प्रकाश, धन-लाभ, सुख-धर्म और अतुल यश; पाप-दृष्टि/योग साथ हो तो अति-कष्ट। (श्लोक 27)','शुभ'),
('Jupiter','hi','गुरु-युत / गुरु-दृष्ट / धनु-मीन में','पुत्र व स्त्री का सुख; सोना, कपड़े, रत्न व भोग की प्राप्ति; शुभ ग्रह से इत्थशाल हो तो राज्य-लाभ। (श्लोक 28)','शुभ'),
('Saturn','hi','शनि-युत / शनि-दृष्ट / मकर-कुम्भ में','वात-रोग, मान-क्षय, आग का डर, धन-हानि; गुरु की दृष्टि हो तो उत्तम/शुभ फल। (श्लोक 29)','अशुभ'),
('Rahu_mukh','hi','मुंथा राहु के मुख-अंशों में (राहु-राशि में राहु के भोग्य अंश)','धन-प्राप्ति, यश, सुख व धर्म की उन्नति; शुक्र/गुरु के योग या दृष्टि से पद-प्राप्ति, सोना-रत्न-कपड़े। (श्लोक 30)','शुभ'),
('Rahu_prishtha','hi','मुंथा राहु के पृष्ठ-अंशों में (भुक्त अंश)','⚠ पाठ-भेद: कुन्तला — शुभप्रद नहीं; ज्योति — कल्याणकारी। default अशुभ (मूल के अनुसार); admin/config से बदलें। पाप-दृष्टि साथ → धन-सुख हानि; जन्म में भी वैसा → गृह-वित्त नाश। (श्लोक 32)','मत-भेद'),
('Rahu_puchchha','hi','मुंथा राहु-राशि से 7वीं राशि (पुच्छ) में','शत्रु से भय और कष्ट; पाप-दृष्टि से धन-सुख की हानि। (श्लोक 31-32)','अशुभ')
INSERT INTO muntha_special_rules (rule_key,language,situation,phal_text) VALUES
('m_sh3','hi','मुंथेश/शुभ ग्रह की दृष्टि मुंथा पर (9,5,3,11 ताजिक-दृष्टि)','सुखदायिनी; मुंथेश पाप हो या मुंथा क्षुत-दृष्टि (1,4,7,10) से दृष्ट → भय व रोग। (श्लोक 3)'),
('m_sh17','hi','मुंथा-स्थित भाव को अशुभ ग्रह क्षुत (1,4,7,10) दृष्टि से देखे','उस भाव का शुभ फल नष्ट, अशुभ फल बढ़ता है। (श्लोक 17)'),
('m_sh18','hi','मुंथा शुभ-ग्रह/स्व-स्वामी से युत-दृष्ट, या पंचवर्गीय-बली, या शुभ/स्वामी से इत्थशाल','उस भाव का शुभ पोषित, अशुभ नष्ट; विपरीत (पाप-युत/दृष्ट, पाप-इत्थशाल, निर्बल) → शुभ नष्ट, अशुभ वृद्धि। (श्लोक 18)'),
('m_sh19','hi','वर्ष-कुंडली में जन्म-लग्न से 7, 12, 6, 8, 4 स्थानों में मुंथा पाप-युत/दृष्ट','मुंथा जिस भाव में है उस भाव का नाश (2रे में धन, 3रे में भाई...); शुभ/स्व-स्वामी-दृष्ट हो → नाश नहीं, शुभ ही फल। (श्लोक 19)'),
('m_sh20','hi','जन्म व वर्ष — दोनों में मुंथा-स्थित भाव पाप-युत/दृष्ट','वह भाव सर्वथा नष्ट; दोनों में शुभ-युत/दृष्ट → वह भाव विशेष रूप से वर्धित। (श्लोक 20)'),
('m_sh21','hi','वर्षेश भी अनिष्ट-गृह (4/6/8/12) में + जन्म में मुंथा-स्थित भाव पर क्रूर-योग','वह जन्म-भाव नष्ट; अनिष्ट-स्थ मुंथा भी शुभ-युक्त हो तो शुभ फल देती है। (श्लोक 21)'),
('m_sh22','hi','उदाहरण-नियम: जन्म-लग्न से 4थे में मुंथा शुभ-युत/दृष्ट','पिता का द्रव्य, जन व भूमि का लाभ; पाप-युत हो तो सरकारी डर, अति-कष्ट, जीविका-हीनता — यही तर्क अन्य स्थानों पर। (श्लोक 22)'),
('m_sh23','hi','वर्ष में मुंथा-स्थित भाव का स्वामी शुभ-दृष्ट','वह राशि जन्म में जिस भाव में है, उस जन्म-भाव की वृद्धि; पाप-युत/दृष्ट → उस जन्म-भाव का नाश; वर्षेश बलवान हो तो मुंथा-कृत अनिष्ट नहीं होता। (श्लोक 23)'),
('m_sh33','hi','जन्म में बली ग्रह वर्ष में निर्बल (या उल्टा)','जन्म-बली/वर्ष-निर्बल → वर्ष के अन्त में अशुभ; जन्म-निर्बल/वर्ष-बली → वर्षारम्भ में अशुभ, बाद में शुभ; दोनों तुल्य → पूरे वर्ष समान फल। (श्लोक 33)'),
('m_sh34','hi','मुंथेश 6/8/12/4 में, अस्त, वक्री, पाप-युत/दृष्ट, या क्रूर-राशि से 4थे-7वें में','शुभ फलदायक नहीं — रोग न भी दे तो धन का नाश देता है। (श्लोक 34)'),
('m_sh35','hi','मुंथेश अष्टमेश से युत या क्षुत (1,4,7,10) दृष्टि से दृष्ट','शुभ नहीं; श्लोक 34 + 35 दोनों योग एक साथ → मरण-योग; एक ही हो → मृत्यु-तुल्य कष्ट। (श्लोक 35)'),
('m_sh36','hi','मुंथा व मुंथेश वर्षप्रवेश में शुभ-युत/दृष्ट','वर्ष के पूर्व-भाग में शुभ फल; पाप-युत/दृष्ट → वर्ष के अन्त में अशुभ; जन्म व वर्ष दोनों में शुभ-योग → सम्पूर्ण वर्ष शुभ। (श्लोक 36)')
INSERT INTO house_engine_config (cfg_key,cfg_value,notes) VALUES
('muntha_daily_motion','0','0 = वर्ष-स्थिर; 1 = 5 कला/दिन'),
('muntha_rahu_mode','bhogya','मुख/पृष्ठ: bhogya या deg15'),
('muntha_rahu_prishtha','ashubh','पाठ-भेद: ashubh (कुन्तला) / shubh (ज्योति)'),
('muntha_use_tajik_drishti','1','युत/दृष्ट जाँच ताजिक दृष्टि से; क्षुत = 1,4,7,10'),
('muntha_janma_bridge','1','श्लोक 19-23 जन्म-वर्ष सेतु नियम')
