-- =============================================================================
-- Auto Business — Muntha Phala (migration 019)
-- Source: Tajik Neelkanthi, Muthaha-phala adhyaya shlokas 1-36
-- (docs/Muntha_Phal_Rules md). Reuses the Tajik (016) drishti service and
-- the Varshesh/Panchavargeeya (018) services. Muntha calc unchanged.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS muntha_bhava_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    house TINYINT NOT NULL, band VARCHAR(16) NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi', phal_text TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_mbp (house, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE band=VALUES(band),phal_text=VALUES(phal_text);

CREATE TABLE IF NOT EXISTS muntha_graha_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rule_key VARCHAR(20) NOT NULL, language VARCHAR(8) NOT NULL DEFAULT 'hi',
    situation VARCHAR(160) NOT NULL, phal_text TEXT NOT NULL, nature VARCHAR(12) NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_mgp (rule_key, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE situation=VALUES(situation),phal_text=VALUES(phal_text),nature=VALUES(nature);

CREATE TABLE IF NOT EXISTS muntha_special_rules (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rule_key VARCHAR(12) NOT NULL, language VARCHAR(8) NOT NULL DEFAULT 'hi',
    situation VARCHAR(200) NOT NULL, phal_text TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_msr (rule_key, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE situation=VALUES(situation),phal_text=VALUES(phal_text);

ON DUPLICATE KEY UPDATE cfg_value=cfg_value;
-- End of migration 019.